// План: specs/cards.md, тест 3.1. Тикет #36b4d7 (עבר QA 17.11.2026). Ребёнок 0500000003 (сессия client2). Только просмотр → @prod-safe.
import { test, expect } from '../../fixtures';
import { HINT, MASK_DOTS_ONLY, waitMasks, expectNoFullCardNumber } from './helpers';

const CHILD_NAME = 'נגה ברק';

test.describe('ארנק ילד — צד ילד', () => {
  test('«ביצוע תשלום» של הילד/ה: «•••• •••• •••• NNNN», שם הילד/ה, «פעיל», הנחיית הצמדה @prod-safe #36b4d7', async ({ asUser }) => {
    const kid = await asUser('client2');
    await kid.goto('/kid');
    await kid.getByRole('button', { name: 'לשימוש בכרטיס' }).click();

    await expect(kid.getByText('ביצוע תשלום').first()).toBeVisible({ timeout: 30_000 });
    const digits = await waitMasks(kid, 1);
    expect(digits).toHaveLength(1);
    expect(digits[0]).toMatch(/^\d{4}$/);
    await expect(kid.getByText(MASK_DOTS_ONLY)).toHaveCount(0);

    await expect(kid.getByText(CHILD_NAME, { exact: true }).first()).toBeVisible();
    await expect(kid.getByText('פעיל', { exact: true }).first()).toBeVisible();
    await expect(kid.getByText(HINT)).toBeVisible();
    await expectNoFullCardNumber(kid);
  });
});
